    phrase: { bpm: 80, loop: true, steps: [[0, 50, 1.9], [0, 57, 1.9], [0, 62, 1.9], [2, 48, 1.9], [2, 55, 1.9], [2, 60, 1.9]] },
    steps: [
      { title: 'Four sawtooths, low', module: 'osc', why: 'Four sawtooths in POLY, an octave down, so the chord has plenty of weight to saturate. POLY gives each key you hold one of the four oscillators (the parts that make the raw tone).\n- MODE POLY: each new key takes the next oscillator in turn.\n- RANGE 16’ on all four: footage comes from organ pipes; 16’ is an octave below normal pitch. A low register makes the saturation weightier.\n- WAVEFORM sawtooth on all four: bright and buzzy.\n- FREQUENCY +0.1 / −0.1 / 0 on 2–4: tiny offsets for a little movement.\n- OSC 1–4 on, VOLUME 6.5 each: fairly hot, so the loop will have plenty to work on.\n- Listen for: dark, heavy chords.',
        set: { 'voice.mode': 'poly', ...SAME('16', 'saw'), 'osc2.freq': 0.06, 'osc3.freq': -0.06, 'osc4.freq': 0, ...ALL_ON, 'mix.osc1': 6.5, 'mix.osc2': 6.5, 'mix.osc3': 6.5, 'mix.osc4': 6.5 } },
      { title: 'Switch in the feedback', module: 'mixer', why: 'With EXT IN (external input) switched on, this app feeds the synth’s own output back into the mixer, as Minimoog players did with a cable. Under chords, the loop saturates the ladder filter with all the notes at once.\n- EXT IN on: connects the feedback path.\n- EXT IN VOLUME 5: the feedback amount. Above 7 the chords start to break up.\n- Listen for: the chords thicken and compress into a dense block. Watch the OVERLOAD lamp, and sweep EXT IN VOLUME to hear the change.', set: { 'mix.extOn': true, 'mix.ext': 5 } },
      { title: 'Filter and shape', module: 'filter', why: 'The filter is a Moog-style low-pass ladder: it keeps the lows and cuts the highs. A mid cutoff and slow-ish attacks let the chords swell into the grit.\n- CUTOFF −0.8 (about 360 Hz): enough brightness for the grit to come through.\n- EMPHASIS 2.5: Moog’s word for resonance. Resonance inside the loop can howl, so it is kept low.\n- AMOUNT OF CONTOUR 3, ATTACK 53 ms: with DECAY 770 ms and SUSTAIN 5, the contour (Moog’s word for envelope) swells each chord brighter.\n- Loudness ATTACK 14 ms, SUSTAIN 10: a soft start, then full level, the volume shape a VCA (voltage-controlled amplifier) gives on other synths.\n- Loudness DECAY 680 ms, DECAY switch on: a fade after release.\n- Listen for: chords push forward and grind a little as they open.',
        set: { 'filter.cutoff': -0.8, 'filter.emphasis': 2.5, 'filter.contour': 3, 'fenv.attack': 1.5, 'fenv.decay': 5, 'fenv.sustain': 5, 'aenv.attack': 1, 'aenv.decay': 4.5, 'aenv.sustain': 10, 'env.decay': true } },
    ],
    context: {
      'mix.ext': 'In this sound: the feedback. Above 7 the chords start to break up.',
      'filter.emphasis': 'In this sound: resonance inside the loop can howl, so keep it low.',
    },
    tweaks: [
      { id: 'mix.ext', try: 'Sweep from 0 to 8 while a chord holds', hear: 'Clean, then compressed, then saturated.' },
      { id: 'fx.chorusOn', try: 'Switch the chorus on with I', hear: 'The grit spreads out into a wide, rough pad.' },
    ],
